// ListAutoPaging: Listar emisores, todos, página por página: for x, err := range …
func (s *IssuersService) ListAutoPaging(ctx context.Context, params *ListIssuersParams, opts ...RequestOption) iter.Seq2[Issuer, error] {
	return listAll[Issuer](ctx, s.c, "/v1/issuers", params, opts)
}

