// WebhookEndpointsService: Webhooks (client.WebhookEndpoints).
type WebhookEndpointsService struct{ c *Client }

// Create: Crear un webhook
//
// La respuesta trae el secreto de firma (secret) una sola vez.
//
// POST /v1/webhook_endpoints
//
// https://fiscalisto.com/docs/api/referencia/webhooks/create-webhook-endpoint
func (s *WebhookEndpointsService) Create(ctx context.Context, params *CreateWebhookEndpointParams, opts ...RequestOption) (*WebhookEndpoint, error) {
	out := new(WebhookEndpoint)
	if err := s.c.do(ctx, "POST", "/v1/webhook_endpoints", params, nil, true, out, opts); err != nil {
		return nil, err
	}
	return out, nil
}

// List: Listar webhooks
//
// Los webhooks del modo de la llave. Hasta 16 por modo.
//
// GET /v1/webhook_endpoints
//
// https://fiscalisto.com/docs/api/referencia/webhooks/list-webhook-endpoints
func (s *WebhookEndpointsService) List(ctx context.Context, params *ListWebhookEndpointsParams, opts ...RequestOption) (*Page[WebhookEndpoint], error) {
	return list[WebhookEndpoint](ctx, s.c, "/v1/webhook_endpoints", params, "", opts)
}

// ListAutoPaging: Listar webhooks, todos, página por página: for x, err := range …
func (s *WebhookEndpointsService) ListAutoPaging(ctx context.Context, params *ListWebhookEndpointsParams, opts ...RequestOption) iter.Seq2[WebhookEndpoint, error] {
	return listAll[WebhookEndpoint](ctx, s.c, "/v1/webhook_endpoints", params, opts)
}

// Get: Ver un webhook
//
// Un webhook: su dirección, los eventos que recibe y si sus entregas fallan. El secreto solo viene al crearlo.
//
// GET /v1/webhook_endpoints/{id}
//
// https://fiscalisto.com/docs/api/referencia/webhooks/get-webhook-endpoint
